"""Find index in string of number (possibly) with error bars immediately
    before the decimal point.

    Parameters
    ----------
    num_str : str
        String representation of a float, possibly with error bars in parens.

    Returns
    -------
    pos : int
        String index of digit before decimal point.

    Examples
    --------
    >>> find_last_dig('5.555')
    0
    >>> find_last_dig('-5.555')
    1
    >>> find_last_dig('-567.555')
    3
    >>> find_last_dig('-567.555(45)')
    3
    >>> find_last_dig('-567(45)')
    3
    """
def find_last_dig(num_str: Any) -> object {
    pos = num_str.find(".");
    assert (pos != 0);
    if (pos < 0) {
        pos = num_str.find("(");
        assert (pos != 0);
    }
    if (pos < 0) {
        pos = len(num_str);
        assert (pos != 0);
    }
    pos = pos - 1;
    return pos;
}

"""Figure out what layers should have reductions."""
def calc_reduction_layers(num_cells: Any, num_reduction_layers: Any) -> object {
    reduction_layers = [];
    for pool_num in range(1, (num_reduction_layers + 1)) {
        layer_num = (float(pool_num) / (num_reduction_layers + 1)) * num_cells;
        layer_num = int(layer_num);
        reduction_layers.append(layer_num);
    }
    return reduction_layers;
}

"""
    Function replacement for if-else to use in expressions.

        >>> x = 2
        >>> cond(x % 2 == 0, "even", "odd")
        'even'
        >>> cond(x % 2 == 0, "even", "odd") + '_row'
        'even_row'
    """
def cond(predicate: Any, consequence: Any, alternative: Any = None) -> object {
    if predicate {
        return consequence;
    } else {
        return alternative;
    }
}
